(function () {
  if (window.__onlydmInstalled) return;
  window.__onlydmInstalled = true;
  var CFG = __ONLYDM_CONFIG__;
  var STYLE_ID = 'onlydm-hide';
  var lastPath = null;

  function post(msg) {
    try { window.ReactNativeWebView.postMessage(JSON.stringify(msg)); } catch (e) {}
  }

  function norm(p) {
    var out = [];
    String(p).replace(/\\/g, '/').split('/').forEach(function (s) {
      if (s === '' || s === '.') return;
      if (s === '..') out.pop(); else out.push(s);
    });
    return '/' + out.join('/') + (/\/$/.test(p) && out.length ? '/' : '');
  }
  function base(p) { return norm(p).toLowerCase().replace(/\/$/, ''); }
  function under(path, prefixes) {
    var p = base(path);
    return prefixes.some(function (x) { var b = base(x); return p === b || p.indexOf(b + '/') === 0; });
  }
  // Pages that live under a shared prefix but are not one shared item (a song's page, /reels/audio/...).
  var NOT_ITEMS = ['audio'];
  function isShared(path) {
    var p = base(path);
    if (NOT_ITEMS.indexOf(p.split('/')[2]) !== -1) return false;
    return CFG.sharedContentPathPrefixes.some(function (x) { return p.indexOf(base(x) + '/') === 0; });
  }

  function ensureStyle() {
    if (document.getElementById(STYLE_ID)) return;
    var s = document.createElement('style');
    s.id = STYLE_ID;
    s.textContent = CFG.css;
    var parent = document.head || document.documentElement;
    if (!parent) return;
    parent.appendChild(s);
  }

  function reportRoute() {
    var path = location.pathname;
    if (path === lastPath) return;
    // A page reached some other way (the Navigation API, a router that skips history) still has to pass.
    if (!under(path, CFG.allowedPathPrefixes)) {
      lastPath = path;
      if (!check(location.href) && isShared(path)) { try { history.back(); } catch (e) {} }
      return;
    }
    // Before <html> exists (Android runs this that early), try again on the next change.
    if (!document.documentElement) return;
    lastPath = path;
    // Lets the pack's CSS target one page (e.g. the inbox list) without touching others.
    try { document.documentElement.setAttribute('data-onlydm-route', path); } catch (e) {}
    post({ type: 'route', path: path });
  }

  /** Returns true when navigation to `url` should proceed. */
  function check(url) {
    var u;
    try { u = new URL(String(url), location.href); } catch (e) { return true; }
    if (u.host !== location.host) return true;
    if (under(u.pathname, CFG.allowedPathPrefixes)) return true;
    if (isShared(u.pathname)) { post({ type: 'shared', url: u.href }); return false; }
    location.replace(CFG.startUrl);
    return false;
  }

  ['pushState', 'replaceState'].forEach(function (name) {
    var orig = history[name];
    history[name] = function (state, title, url) {
      if (url != null && !check(url)) return;
      var r = orig.apply(history, arguments);
      reportRoute();
      return r;
    };
  });

  // Newer WebKit routes in-page navigation through the Navigation API, which bypasses pushState.
  try {
    if (window.navigation && typeof window.navigation.addEventListener === 'function') {
      window.navigation.addEventListener('navigate', function (e) {
        try {
          if (!e.destination || !e.destination.url) return;
          if (!check(e.destination.url) && e.cancelable) e.preventDefault();
        } catch (err) {}
      });
    }
  } catch (e) {}

  window.addEventListener('popstate', function () {
    if (check(location.href)) reportRoute();
  });

  ensureStyle();
  if (check(location.href)) reportRoute();

  var timer = null;
  new MutationObserver(function () {
    clearTimeout(timer);
    timer = setTimeout(function () { ensureStyle(); reportRoute(); }, 150);
  }).observe(document, { childList: true, subtree: true });
})();
true;
